/* From Uiverse.io by elijahgummer  - Tags: simple, animation, minimalist, gradient, loading, card */
.__UIV_SCOPE__ .card {
  max-width: 250px;
  width: 100%;
  background: #fff;
  padding: 30px;
  border-radius: 10px;
  border: 1px solid #d9d9d9;
}
.__UIV_SCOPE__ .card .header {
  display: flex;
  align-items: center;
}
.__UIV_SCOPE__ .header .img {
  height: 45px;
  width: 45px;
  background: #d9d9d9;
  border-radius: 50%;
  position: relative;
  overflow: hidden;
}
.__UIV_SCOPE__ .header .details {
  margin-left: 20px;
}
.__UIV_SCOPE__ .details span {
  display: block;
  background: #d9d9d9;
  border-radius: 10px;
  overflow: hidden;
  position: relative;
}
.__UIV_SCOPE__ .details .name {
  height: 12px;
  width: 70px;
}
.__UIV_SCOPE__ .details .about {
  height: 13px;
  width: 120px;
  margin-top: 10px;
}
.__UIV_SCOPE__ .card .description {
  margin: 25px 0;
}
.__UIV_SCOPE__ .description .line {
  background: #d9d9d9;
  border-radius: 10px;
  height: 11px;
  margin: 10px 0;
  overflow: hidden;
  position: relative;
}
.__UIV_SCOPE__ .description .line-1 {
  width: calc(100% - 15%);
}
.__UIV_SCOPE__ .description .line-3 {
  width: calc(100% - 40%);
}
.__UIV_SCOPE__ .card .btns {
  display: flex;
}
.__UIV_SCOPE__ .card .btns .btn {
  height: 25px;
  width: 100%;
  background: #d9d9d9;
  border-radius: 25px;
  position: relative;
  overflow: hidden;
}
.__UIV_SCOPE__ .btns .btn-1 {
  margin-right: 8px;
}
.__UIV_SCOPE__ .btns .btn-2 {
  margin-left: 8px;
}
.__UIV_SCOPE__ .header .img::before,
.__UIV_SCOPE__ .details span::before,
.__UIV_SCOPE__ .description .line::before,
.__UIV_SCOPE__ .btns .btn::before {
  position: absolute;
  content: "";
  height: 100%;
  width: 100%;
  background-image: linear-gradient(
    to right,
    #d9d9d9 0%,
    rgba(0, 0, 0, 0.05) 20%,
    #d9d9d9 40%,
    #d9d9d9 100%
  );
  background-repeat: no-repeat;
  background-size: 450px 400px;
  animation: shimmer 1s linear infinite;
}
.__UIV_SCOPE__ .header .img::before {
  background-size: 650px 600px;
}
.__UIV_SCOPE__ .details span::before {
  animation-delay: 0.2s;
}
.__UIV_SCOPE__ .btns .btn-2::before {
  animation-delay: 0.22s;
}
@keyframes shimmer {
  0% {
    background-position: -450px 0;
  }
  100% {
    background-position: 450px 0;
  }
}
